    return list(map(int, input().split()))

def main():
    N = int(input())
    graph = [[] for _ in range(N)]
    for _ in range(N - 1):
        U, V = read_ints()
        graph[U].append(V)
        graph[V].append(U)

    def calculate_potential(start_order):
        started = [False] * N
        started[start_order[0]] = True
        potential_sum = 1

        for core in start_order[1:]:
            for neighbor in graph[core]:
                if started[neighbor]:
                    started[core] = True
                    potential_sum += 1
                    break

        for core in start_order:
            for neighbor in graph[core]:
                if started[neighbor]:
                    started[core] = True
                    potential_sum += 2 ** (N - 1 - len(started))
                    break

        return potential_sum

    def backtrack(order, used, max_sum):
        if len(order) == N:
            return calculate_potential(order)

        for core in range(N):
            if not used[core]:
                used[core] = True
                current_sum = backtrack(order + [core], used, max_sum)
                max_sum = max(max_sum, current_sum)
                used[core] = False
        return max_sum

    max_sum = 0
    used = [False] * N
    max_sum = backtrack([], used, max_sum)
    print(max_sum)

